    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 8 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 8 and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        stack.append((nx,ny))
            # Preserve 2x2 blocks as the common square color.
            for x, y in comp:
                if any(x+1 < h and y+1 < w and all(grid[a][b] == 8 for a,b in
                       ((x,y),(x+1,y),(x,y+1),(x+1,y+1))) for _ in [0]):
                    out[x][y] = 1
            rest = [(x,y) for x,y in comp if out[x][y] != 1]
            if rest:
                minr, maxr = min(x for x,y in rest), max(x for x,y in rest)
                minc, maxc = min(y for x,y in rest), max(y for x,y in rest)
