def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}

    # Find a disjoint cover by 2x2 squares and L triominoes, preferring squares.
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            if all(p in occupied for p in box):
                pieces.append((box, 1, 0))
            for missing, color in [((r, c), 2), ((r + 1, c), 3), ((r, c + 1), 4)]:
                tri = [p for p in box if p != missing]
                if all(p in occupied for p in tri):
                    pieces.append((tri, color, 1))

    pieces.sort(key=lambda p: (p[2], -len(p[0])))
    best = None

    def search(remaining, chosen):
        nonlocal best
        if not remaining:
            score = (sum(1 for _, color, _ in chosen if color != 1), -len(chosen))
            if best is None or score < best[0]:
                best = (score, chosen[:])
            return
        if best is not None and len(chosen) >= len(best[1]):
            return
        cell = min(remaining)
        options = [p for p in pieces if cell in p[0] and all(q in remaining for q in p[0])]
        if not options:
            return
        for piece in options:
            search(remaining - set(piece[0]), chosen + [piece])

    search(occupied, [])
    if best:
        for cells, color, _ in best[1]:
            for r, c in cells:
                out[r][c] = color
    return out
